head.script:
// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
//
// ********************************************************************

scwin.gReqAcptNo;
scwin.gAnsRnd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gInputTp;
X < !정보--;
셋팅-- > function() {
    scwin.gReqAcptNo = $c.frame.path("../").scwin.gReqAcptNo;
    scwin.gAnsRnd = $c.frame.path("../").scwin.gAnsRnd;
    // alert("자식창:"+gReqAcptNo+","+ gAnsRnd);

} < !정보--;
데이타;
읽어오기-- > async function() {
    const sbmOptions = {
        id : "sbm_dts_inquiry_info",
        action : "/InquiryDisclosure.do",
        ref : "",
        target : "dts_inquiry_info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        fn_GetParentValue();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_inquiry_info",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_inquiry_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 가우스헤더 셋팅
        const sbmOptions2 = {
            id : "sbm_dts_inquiry",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_inquiry=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        //  정보 읽어오기
        fn_ReadInfo();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30202.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_cls_dd_onclick
 * @description img_cls_dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_cls_dd_onclick = function() {
    try {
        popUpCalendar2(edt_deadline_dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30202.img_cls_dd_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        // self.close();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30202.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30202.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30202.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name dts_inquiry_info_OnLoadError
 * @description dts_inquiry_info 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_inquiry_info_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_inquiry_info);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30202.dts_inquiry_info_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_inquiry_info_OnLoadCompleted
 * @description dts_inquiry_info 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_inquiry_info_OnLoadCompleted = function(rowcount) {
    try {
        const vProcsEmpNo = dts_inquiry_info.getCellData(1, "EMP_NO");
        if (vProcsEmpNo !== '') {
            scwin.gInputTp = 'M'; // 담당자가 수동으로 답변연결한 경우
            btn_Delete.show("");
        } else {
            scwin.gInputTp = 'A'; // 상장법인이 제출에서 답변을 제출한 경우
            btn_Delete.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30202.dts_inquiry_info_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_inquiry_info_OnSuccess
 * @description inquiry info On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_info_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        // self.close();
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30202.trs_inquiry_info_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_inquiry_info_OnFail
 * @description inquiry info On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_info_OnFail = async function() {
    try {
        await $c.win.alert('trs_inquiry_info.OnFail() :' + trs_inquiry_info.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30202.trs_inquiry_info_OnFail" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    const vDeadlineDd = edt_deadline_dd.getValue();
    if (vDeadlineDd.length < 8) {
        await $c.win.alert("날짜를 올바르게 입력하시오.");
        edt_deadline_dd.focus();
        return;
    }
    dts_inquiry.insertRow();
    dts_inquiry.setCellData(1, "REQ_ACPT_NO", scwin.gReqAcptNo);
    dts_inquiry.setCellData(1, "ANS_RND", scwin.gAnsRnd);
    dts_inquiry.setCellData(1, "ADM_DEADLINE", vDeadlineDd);
    dts_inquiry.setCellData(1, "FINAL_YN", cmb_final_yn.getValue());
    dts_inquiry.setCellData(1, "REMK", txa_remk.getValue());

    // alert(dts_nfaith.text);

    const vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        // alert(dts_again.text);
        trs_inquiry_info.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_inquiry_info",
            action : "/InquiryDisclosure.do",
            ref : "dts_inquiry",
            target : "trs_inquiry_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

// 답변연결 삭제(담당자가 수동으로 연결한것)

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (scwin.gInputTp === 'A') {
        await $c.win.alert("상장법인이 제출한 조회공시답변은 삭제하실 수 없습니다.");
        edt_deadline_dd.focus();
        return;
    }
    const rtn = confirm('조회공시 답변을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_inquiry.insertRow();
        dts_inquiry.setCellData(1, "REQ_ACPT_NO", scwin.gReqAcptNo);
        dts_inquiry.setCellData(1, "ANS_RND", scwin.gAnsRnd);
        trs_inquiry_info.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_inquiry_info",
            action : "/InquiryDisclosure.do",
            ref : "dts_inquiry",
            target : "trs_inquiry_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
